<?php $pageTitle='Shopping Cart'; require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ if(isset($_POST['remove'])) unset($_SESSION['cart'][$_POST['key']]); if(isset($_POST['qty'])) foreach($_POST['qty'] as $k=>$q) if(isset($_SESSION['cart'][$k])) $_SESSION['cart'][$k]['qty']=max(1,(int)$q); redirect('cart.php'); }
$items=cart_items();$tot=cart_totals(); ?>
<main class="section-pad"><div class="container"><h1 class="fw-bold mb-4">Your Cart</h1><?php if(!$items): ?><div class="alert alert-warning">Your cart is empty. <a href="products.php">Shop now</a>.</div><?php else: ?><form method="post"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Price</th><th width="130">Qty</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><b><?= e($it['name']) ?></b><br><small><?= e($it['notes']) ?></small></td><td><?= money($it['price']) ?></td><td><input data-auto-submit class="form-control" name="qty[<?= e($it['cart_key']) ?>]" type="number" min="1" value="<?= $it['qty'] ?>"></td><td><?= money($it['price']*$it['qty']) ?></td><td><button name="remove" value="1" class="btn btn-sm btn-outline-danger" onclick="this.form.key.value='<?= e($it['cart_key']) ?>'">Remove</button></td></tr><?php endforeach; ?></tbody></table></div><input type="hidden" name="key"></form><div class="row justify-content-end"><div class="col-md-4"><div class="p-4 rounded-4 shadow-sm"><p>Subtotal: <b><?= money($tot['subtotal']) ?></b></p><p>Service fee: <b><?= money($tot['fee']) ?></b></p><h4>Total: <?= money($tot['total']) ?></h4><a class="btn btn-red w-100 mt-2" href="checkout.php">Checkout</a></div></div></div><?php endif; ?></div></main><?php require 'includes/footer.php'; ?>